func getPage(t *testing.T, h http.Handler, query string) ([]string, string) {
	t.Helper()
	r := do(t, h, "GET", "/api/invoices?"+query, "key-acme", "")
	if r.Code != http.StatusOK {
		t.Fatalf("list %q: %d %s", query, r.Code, r.Body)
	}
	var p pageBody
	if err := json.Unmarshal(r.Body.Bytes(), &p); err != nil {
		t.Fatal(err)
	}
	var ids []string
	for _, it := range p.Items {
		ids = append(ids, it.ID)
	}
	return ids, p.NextCursor
}

// walkPages follows next_cursor from query until the last page and returns every ID seen, in order.
func walkPages(t *testing.T, h http.Handler, query string) []string {
	t.Helper()
	var all []string
	for cursor := ""; ; {
		q := query
		if cursor != "" {
			q += "&cursor=" + cursor
		}
		ids, next := getPage(t, h, q)
		all = append(all, ids...)
		if next == "" {
			return all
		}
		if len(all) > 1000 {
			t.Fatal("paging does not end")
		}
		cursor = next
	}
}

func TestInvoicesArePagedInCreationOrder(t *testing.T) {
	srv, st := newServer(t)
	want := seedInvoices(t, st, time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC), 25)
	if got := walkPages(t, srv, "limit=7"); !equalIDs(got, want) {
		t.Fatalf("walk with limit 7:\n got %v\nwant %v", got, want)
	}
	if got := walkPages(t, srv, ""); !equalIDs(got, want[:20]) {
		t.Fatalf("default walk should stop after 20 of 25 with the next page, got %d items", len(got))
	}
}

func TestThePageSizeDefaultsToTwentyAndNextCursorIsEmptyOnTheLastPage(t *testing.T) {
	srv, st := newServer(t)
	seedInvoices(t, st, time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC), 25)
	ids, next := getPage(t, srv, "")
	if len(ids) != 20 || next == "" {
		t.Fatalf("first page: %d items, next %q", len(ids), next)
	}
	ids, next = getPage(t, srv, "cursor="+next)
	if len(ids) != 5 || next != "" {
		t.Fatalf("last page: %d items, next %q", len(ids), next)
	}
}

func TestAnAccountWithNoInvoicesGetsAnEmptyPage(t *testing.T) {
	srv, _ := newServer(t)
	r := do(t, srv, "GET", "/api/invoices", "key-globex", "")
	if r.Code != http.StatusOK || !strings.Contains(r.Body.String(), `"items":[]`) || !strings.Contains(r.Body.String(), `"next_cursor":""`) {
		t.Fatalf("empty list: %d %s", r.Code, r.Body)
	}
}

func TestExactlyOnePageHasNoNextCursor(t *testing.T) {
	srv, st := newServer(t)
	want := seedInvoices(t, st, time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC), 20)
	ids, next := getPage(t, srv, "")
	if !equalIDs(ids, want) || next != "" {
		t.Fatalf("got %d items, next %q", len(ids), next)
	}
}

func TestLimitBoundsAreAcceptedAndEverythingElseIsInvalid(t *testing.T) {
	srv, st := newServer(t)
	seedInvoices(t, st, time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC), 3)
	for _, q := range []string{"limit=1", "limit=100"} {
		if ids, _ := getPage(t, srv, q); len(ids) != 3 {
			t.Fatalf("%s: %d items", q, len(ids))
		}
	}
	for _, q := range []string{"limit=0", "limit=101", "limit=-1", "limit=+5", "limit=1.5", "limit=abc", "limit=", "limit=10&limit=20", "limit=99999999999999999999999"} {
		r := do(t, srv, "GET", "/api/invoices?"+q, "key-acme", "")
		if r.Code != http.StatusBadRequest || !strings.Contains(r.Body.String(), `"error":"invalid_limit"`) {
			t.Fatalf("%s: %d %s", q, r.Code, r.Body)
		}
	}
}

func TestAnUnreadableCursorIsInvalid(t *testing.T) {
	srv, st := newServer(t)
	seedInvoices(t, st, time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC), 3)
	garbage := base64.RawURLEncoding.EncodeToString([]byte("nonsense"))
	notANumber := base64.RawURLEncoding.EncodeToString([]byte("soon|inv_00001"))
	noID := base64.RawURLEncoding.EncodeToString([]byte("1767323045000000000|"))
	for _, c := range []string{"!!!", garbage, notANumber, noID, ""} {
		r := do(t, srv, "GET", "/api/invoices?cursor="+c, "key-acme", "")
		if r.Code != http.StatusBadRequest || !strings.Contains(r.Body.String(), `"error":"invalid_cursor"`) {
			t.Fatalf("cursor %q: %d %s", c, r.Code, r.Body)
		}
	}
}

func TestPagingNeitherSkipsNorRepeatsInvoicesCreatedBetweenPages(t *testing.T) {
	srv, st := newServer(t)
	start := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	before := seedInvoices(t, st, start, 5)
	first, cursor := getPage(t, srv, "limit=2")

	// Created between the page requests: one sharing the newest timestamp, then three later ones.
	same := seedInvoices(t, st, start.Add(4*time.Second), 1)
	later := seedInvoices(t, st, start.Add(10*time.Second), 3)
	want := append(append(append([]string{}, before...), same...), later...)

	rest := walkPages(t, srv, "limit=2&cursor="+cursor)
	if got := append(first, rest...); !equalIDs(got, want) {
		t.Fatalf("paging around new invoices:\n got %v\nwant %v", got, want)
	}
}

func TestInvoicesAreOrderedByCreationTimeNotByID(t *testing.T) {
	srv, st := newServer(t)
	start := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	c, err := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, start)
	if err != nil {
		t.Fatal(err)
	}
	var newestFirst []string
	for i := 2; i >= 0; i-- {
		inv, err := st.CreateInvoice(store.Invoice{AccountID: "acc_acme", CustomerID: c.ID, Lines: []store.LineItem{{Description: "Seats", Quantity: 1, UnitCents: 100}}}, start.Add(time.Duration(i)*time.Second))
		if err != nil {
			t.Fatal(err)
		}
		newestFirst = append([]string{inv.ID}, newestFirst...)
	}
	// IDs were issued in the order the invoices were created, but times run backwards, so the oldest by time is last issued.
	if got := walkPages(t, srv, "limit=1"); !equalIDs(got, newestFirst) {
		t.Fatalf("got %v, want %v", got, newestFirst)
	}
}

func equalIDs(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
